#include "msp.h"
void MspPort::begin(){resetParser();}void MspPort::resetParser(){state_=ParseState::DOLLAR;index_=0;checksum_=0;response_.valid=false;}
bool MspPort::request(uint8_t command,const uint8_t*payload,uint8_t length){if(awaiting_||length>64)return false;uint8_t checksum=length^command;serial_.write('$');serial_.write('M');serial_.write('<');serial_.write(length);serial_.write(command);for(uint8_t i=0;i<length;i++){serial_.write(payload[i]);checksum^=payload[i];}serial_.write(checksum);wanted_=command;awaiting_=true;requestStartedMs_=millis();return true;}
void MspPort::update(){while(serial_.available())parseByte((uint8_t)serial_.read());if(awaiting_&&millis()-requestStartedMs_>30){awaiting_=false;timeoutCount_++;resetParser();}}
void MspPort::parseByte(uint8_t v){switch(state_){case ParseState::DOLLAR:if(v=='$')state_=ParseState::M;break;case ParseState::M:state_=v=='M'?ParseState::DIRECTION:ParseState::DOLLAR;break;case ParseState::DIRECTION:state_=v=='>'?ParseState::LENGTH:ParseState::DOLLAR;break;case ParseState::LENGTH:if(v>64){resetParser();break;}response_.length=v;checksum_=v;state_=ParseState::COMMAND;break;case ParseState::COMMAND:response_.command=v;checksum_^=v;index_=0;state_=response_.length?ParseState::PAYLOAD:ParseState::CHECKSUM;break;case ParseState::PAYLOAD:response_.payload[index_++]=v;checksum_^=v;if(index_==response_.length)state_=ParseState::CHECKSUM;break;case ParseState::CHECKSUM:response_.valid=(v==checksum_&&response_.command==wanted_);awaiting_=false;state_=ParseState::DOLLAR;break;}}
bool MspPort::takeResponse(MspResponse&out){if(!response_.valid)return false;out=response_;response_.valid=false;return true;}
